import{readFileSync,realpathSync}from'node:fs';
import{fileURLToPath}from'node:url';

// Existing, working helper. Preserve its exported behavior.
export function normalizeSegments(input){
  if(typeof input!=='string')throw Error('invalid path');
  const segments=[];
  for(const part of input.split('/')){
    if(part===''||part==='.')continue;
    if(part==='..'){segments.pop();continue;}
    segments.push(part);
  }
  return segments;
}

function assertPathString(value,name){
  if(typeof value!=='string')throw Error(name+' must be a nonempty string');
  if(value.length===0)throw Error(name+' must be a nonempty string');
  if(value.indexOf('\u0000')!==-1)throw Error(name+' must not contain NUL');
}

export function resolveWithin(root,candidate){
  assertPathString(root,'root');
  assertPathString(candidate,'candidate');
  if(!root.startsWith('/'))throw Error('root must start with /');
  const rootSegments=normalizeSegments(root);
  const resolvedSegments=candidate.startsWith('/')?[]:rootSegments.slice();
  for(const part of candidate.split('/')){
    if(part===''||part==='.')continue;
    if(part==='..'){if(resolvedSegments.length>0)resolvedSegments.pop();continue;}
    resolvedSegments.push(part);
  }
  const inside=resolvedSegments.length>=rootSegments.length&&
    rootSegments.every((segment,index)=>resolvedSegments[index]===segment);
  const resolved=resolvedSegments.length===0?'/':'/'+resolvedSegments.join('/');
  const relative=inside?resolvedSegments.slice(rootSegments.length).join('/'):null;
  return {inside,resolved,relative};
}

function fail(message){
  process.stderr.write(message+'\n');
  process.exitCode=2;
}

function runCli(){
  const args=process.argv.slice(2);
  if(args.length!==1){fail('usage: node path-scope.js INPUT_JSON_FILE');return;}
  let payload;
  try{
    payload=JSON.parse(readFileSync(args[0],'utf8'));
  }catch(error){
    fail('cannot read or parse input file: '+error.message);
    return;
  }
  if(typeof payload!=='object'||payload===null||Array.isArray(payload)){
    fail('input JSON must be a non-null, non-array object with {root,candidate}');
    return;
  }
  let result;
  try{
    result=resolveWithin(payload.root,payload.candidate);
  }catch(error){
    fail('invalid path input: '+error.message);
    return;
  }
  process.stdout.write(JSON.stringify(result)+'\n');
}

function isDirectRun(){
  const entry=process.argv[1];
  if(typeof entry!=='string'||entry.length===0)return false;
  try{
    return realpathSync(entry)===realpathSync(fileURLToPath(import.meta.url));
  }catch{return false;}
}

if(isDirectRun())runCli();

