import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync}from'node:child_process';
import{mkdirSync,rmSync,writeFileSync,readFileSync,mkdtempSync,existsSync}from'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath}from'node:url';
import {normalizeSegments, resolveWithin} from '../path-scope.js';

const MODULE_PATH=fileURLToPath(new URL('../path-scope.js',import.meta.url));
const NODE=process.execPath;

function cli(args){
  try{
    const stdout=execFileSync(NODE,[MODULE_PATH,...args],{encoding:'utf8',stdio:'pipe'});
    return {code:0,stdout,stderr:''};
  }catch(error){
    return {code:error.status,stdout:(error.stdout??'')+'' ,stderr:(error.stderr??'')+''};
  }
}

test('the existing helper behavior is preserved',()=>{
  assert.deepEqual(normalizeSegments('/a//b/./c'),['a','b','c']);
  assert.deepEqual(normalizeSegments('a/../../b'),['b']);
  assert.deepEqual(normalizeSegments('..foo/.../.hidden'),['..foo','...','..hidden']);
  assert.deepEqual(normalizeSegments(''),[]);
  assert.throws(()=>normalizeSegments(42),Error);
});

test('spec example: relative candidate climbs within root',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','../ws/sub/../file.txt'),
    {inside:true,resolved:'/srv/ws/file.txt',relative:'file.txt'});
});

test('spec example: absolute sibling is outside',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','/srv/wsx'),
    {inside:false,resolved:'/srv/wsx',relative:null});
});

test('textual prefix is not containment',()=>{
  assert.deepEqual(resolveWithin('/a/b','/a/bc'),
    {inside:false,resolved:'/a/bc',relative:null});
  assert.deepEqual(resolveWithin('/a/b','/a/b/c'),
    {inside:true,resolved:'/a/b/c',relative:'c'});
});

test('same location reports empty relative path',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','.'),
    {inside:true,resolved:'/srv/ws',relative:''});
  assert.deepEqual(resolveWithin('/srv/ws','sub/../.'),
    {inside:true,resolved:'/srv/ws',relative:''});
  assert.deepEqual(resolveWithin('/srv/ws/','/srv/ws'),
    {inside:true,resolved:'/srv/ws',relative:''});
});

test('absolute candidate inside root',()=>{
  assert.deepEqual(resolveWithin('/srv/ws','/srv/ws/a/b'),
    {inside:true,resolved:'/srv/ws/a/b',relative:'a/b'});
});

test('.. clamps at the filesystem root and never climbs above it',()=>{
  assert.deepEqual(resolveWithin('/a','../../x'),
    {inside:false,resolved:'/x',relative:null});
  assert.deepEqual(resolveWithin('/a/b','../../..'),
    {inside:false,resolved:'/',relative:null});
  assert.deepEqual(resolveWithin('/','../x'),
    {inside:true,resolved:'/x',relative:'x'});
});

test('root at filesystem root contains every absolute path',()=>{
  assert.deepEqual(resolveWithin('/','a/b'),
    {inside:true,resolved:'/a/b',relative:'a/b'});
  assert.deepEqual(resolveWithin('/','/'),
    {inside:true,resolved:'/',relative:''});
});

test('backslash is an ordinary character, never a separator',()=>{
  assert.deepEqual(resolveWithin('/a','a\\b'),
    {inside:true,resolved:'/a/a\\b',relative:'a\\b'});
  assert.deepEqual(normalizeSegments('x\\y'),['x\\y']);
});

test('dot-adjacent names are ordinary segments',()=>{
  assert.deepEqual(resolveWithin('/r','..foo/.../.hidden/.'),
    {inside:true,resolved:'/r/..foo/.../.hidden',relative:'..foo/.../.hidden'});
});

test('trailing and duplicate slashes are dropped in the result',()=>{
  assert.deepEqual(resolveWithin('/srv//ws/','sub/'),
    {inside:true,resolved:'/srv/ws/sub',relative:'sub'});
  assert.deepEqual(resolveWithin('//a//','b//'),
    {inside:true,resolved:'/a/b',relative:'b'});
});

test('inputs are not mutated',()=>{
  const root='/srv/ws';
  const candidate='sub/../x/';
  resolveWithin(root,candidate);
  assert.equal(root,'/srv/ws');
  assert.equal(candidate,'sub/../x/');
});

test('invalid inputs throw an Error',()=>{
  assert.throws(()=>resolveWithin('','x'),Error);
  assert.throws(()=>resolveWithin('/a',''),Error);
  assert.throws(()=>resolveWithin('a','x'),Error);
  assert.throws(()=>resolveWithin('/a','b\u0000'),Error);
  assert.throws(()=>resolveWithin('/a\u0000','b'),Error);
  assert.throws(()=>resolveWithin(null,'x'),Error);
  assert.throws(()=>resolveWithin('/a',null),Error);
  assert.throws(()=>resolveWithin(1,'x'),Error);
  assert.throws(()=>resolveWithin('/a',2),Error);
  assert.throws(()=>resolveWithin(undefined,undefined),Error);
});

test('CLI: valid input prints exactly the API result and exits 0',()=>{
  const dir=mkdtempSync(path.join(os.tmpdir(),'path-scope-cli-'));
  try{
    const input=path.join(dir,'input.json');
    writeFileSync(input,JSON.stringify({root:'/srv/ws',candidate:'../ws/sub/../file.txt',ignored:{}}));
    const result=cli([input]);
    assert.equal(result.code,0);
    assert.equal(result.stderr,'');
    assert.equal(result.stdout,'{"inside":true,"resolved":"/srv/ws/file.txt","relative":"file.txt"}\n');
  }finally{rmSync(dir,{recursive:true,force:true});}
});

test('CLI: outside candidate prints inside:false and relative:null',()=>{
  const dir=mkdtempSync(path.join(os.tmpdir(),'path-scope-cli-'));
  try{
    const input=path.join(dir,'input.json');
    writeFileSync(input,JSON.stringify({root:'/srv/ws',candidate:'/srv/wsx'}));
    const result=cli([input]);
    assert.equal(result.code,0);
    assert.equal(result.stderr,'');
    assert.equal(result.stdout,'{"inside":false,"resolved":"/srv/wsx","relative":null}\n');
  }finally{rmSync(dir,{recursive:true,force:true});}
});

test('CLI: invalid argument counts exit 2 with nonempty stderr and no stdout',()=>{
  for(const args of[[],['one.json','two.json']]){
    const result=cli(args);
    assert.equal(result.code,2);
    assert.ok(result.stderr.length>0);
    assert.equal(result.stdout,'');
  }
});

test('CLI: missing file, bad JSON, and bad shapes exit 2 with nonempty stderr and no stdout',()=>{
  const dir=mkdtempSync(path.join(os.tmpdir(),'path-scope-cli-'));
  try{
    const missing=path.join(dir,'nope.json');
    const badJson=path.join(dir,'bad.json');
    writeFileSync(badJson,'{not json');
    const cases=[[missing],
      [badJson],
      ...['null','[]','"x"',JSON.stringify([]),JSON.stringify(null),JSON.stringify('s'),JSON.stringify(7)]
        .map((content)=>{
          const file=path.join(dir,'shape.json');
          writeFileSync(file,content);
          return [file];
        })];
    for(const args of cases){
      const result=cli(args);
      assert.equal(result.code,2,args[0]);
      assert.ok(result.stderr.length>0,args[0]);
      assert.equal(result.stdout,'');
    }
  }finally{rmSync(dir,{recursive:true,force:true});}
});

test('CLI: object missing fields or with invalid path values exits 2',()=>{
  const dir=mkdtempSync(path.join(os.tmpdir(),'path-scope-cli-'));
  try{
    const shapes=[
      {},
      {root:'/a'},
      {candidate:'b'},
      {root:'no-slash',candidate:'b'},
      {root:'/a',candidate:null},
      {root:'/a\u0000b',candidate:'c'},
    ];
    for(const shape of shapes){
      const file=path.join(dir,'shape.json');
      writeFileSync(file,JSON.stringify(shape));
      const result=cli([file]);
      assert.equal(result.code,2,JSON.stringify(shape));
      assert.ok(result.stderr.length>0,JSON.stringify(shape));
      assert.equal(result.stdout,'');
    }
  }finally{rmSync(dir,{recursive:true,force:true});}
});

test('importing the module does not run the CLI',()=>{
  const dir=mkdtempSync(path.join(os.tmpdir(),'path-scope-import-'));
  try{
    const importer=path.join(dir,'importer.mjs');
    writeFileSync(importer,
      `import {resolveWithin} from ${JSON.stringify('file://'+MODULE_PATH)};\n`+
      `console.log(JSON.stringify(resolveWithin('/srv/ws','sub/file.txt')));\n`);
    const stdout=execFileSync(NODE,[importer,'extra','args','here'],{encoding:'utf8'});
    assert.equal(stdout,JSON.stringify(
      {inside:true,resolved:'/srv/ws/sub/file.txt',relative:'sub/file.txt'})+'\n');
  }finally{rmSync(dir,{recursive:true,force:true});}
});

